step3_testbench.spice:
* ngspice testbench for 11-stage ring oscillator
.lib ${SKY130_PDK} tt

* Define parameters for W and L
.param W_n=1 L_n=0.15 W_p=2 L_p=0.15
.param W_xm1=W_n L_xm1=L_n W_xm2=W_p L_xm2=L_p
.param W_xm3=W_n L_xm3=L_n W_xm4=W_p L_xm4=L_p
.param W_xm5=W_n L_xm5=L_n W_xm6=W_p L_xm6=L_p
.param W_xm7=W_n L_xm7=L_n W_xm8=W_p L_xm8=L_p
.param W_xm9=W_n L_xm9=L_n W_xm10=W_p L_xm10=L_p
.param W_xm11=W_n L_xm11=L_n W_xm12=W_p L_xm12=L_p
.param W_xm13=W_n L_xm13=L_n W_xm14=W_p L_xm14=L_p
.param W_xm15=W_n L_xm15=L_n W_xm16=W_p L_xm16=L_p
.param W_xm17=W_n L_xm17=L_n W_xm18=W_p L_xm18=L_p
.param W_xm19=W_n L_xm19=L_n W_xm20=W_p L_xm20=L_p
.param W_xm21=W_n L_xm21=L_n W_xm22=W_p L_xm22=L_p

* DUT
xm1 N001 Osc 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
VDD VDD 0 1.8
xm2 N001 Osc VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm2} l={L_xm2}
xm3 N002 N001 0 0 sky130_fd_pr__nfet_01v8 w={W_xm3} l={L_xm3}
xm4 N002 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm4} l={L_xm4}
xm5 N003 N002 0 0 sky130_fd_pr__nfet_01v8 w={W_xm5} l={L_xm5}
xm6 N003 N002 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm6} l={L_xm6}
xm7 N004 N003 0 0 sky130_fd_pr__nfet_01v8 w={W_xm7} l={L_xm7}
xm8 N004 N003 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm8} l={L_xm8}
xm9 N005 N004 0 0 sky130_fd_pr__nfet_01v8 w={W_xm9} l={L_xm9}
xm10 N005 N004 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm10} l={L_xm10}
xm11 N006 N005 0 0 sky130_fd_pr__nfet_01v8 w={W_xm11} l={L_xm11}
xm12 N006 N005 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm12} l={L_xm12}
xm13 N007 N006 0 0 sky130_fd_pr__nfet_01v8 w={W_xm13} l={L_xm13}
xm14 N007 N006 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm14} l={L_xm14}
xm15 N008 N007 0 0 sky130_fd_pr__nfet_01v8 w={W_xm15} l={L_xm15}
xm16 N008 N007 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm16} l={L_xm16}
xm17 N009 N008 0 0 sky130_fd_pr__nfet_01v8 w={W_xm17} l={L_xm17}
xm18 N009 N008 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm18} l={L_xm18}
xm19 N010 N009 0 0 sky130_fd_pr__nfet_01v8 w={W_xm19} l={L_xm19}
xm20 N010 N009 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm20} l={L_xm20}
xm21 Osc N010 0 0 sky130_fd_pr__nfet_01v8 w={W_xm21} l={L_xm21}
xm22 Osc N010 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm22} l={L_xm22}

* Initial condition to start oscillation
.ic v(Osc)=1.8

.control
  tran 1p 10n

  * Measure oscillation period and frequency
  meas tran period trig v(Osc) val=0.9 rise=3 targ v(Osc) val=0.9 rise=4
  let fosc = 1 / period
  print fosc

  * Measure delay per stage (11 stages, 2 transitions per period)
  let stage_delay = period / 22
  print stage_delay

  * Measure average current and power
  meas tran ivdd avg i(VDD) from=2n to=10n
  let total_power = -ivdd * 1.8
  let power_per_stage = total_power / 11
  print total_power
  print power_per_stage

  * Calculate Power Delay Product (PDP) per stage
  let pdp = power_per_stage * stage_delay
  print pdp

  quit
.endc
.end

